var t=[{title:`Woher der Lärm kommt`,text:`Wiederholte Fußaufsätze, Seilspringen, Burpees, harte Landungen, rollende Ausrüstung und fallen gelassene Kurzhanteln tragen alle Schall durch ein Gebäude. Dünne Böden können einen kleinen Aufprall laut klingen lassen. Eine Routine, die im Studio im Erdgeschoss lautlos wirkt, kann Menschen unter einer Wohnung im Obergeschoss stören.`},{title:`Leisere Tausche`,text:`Ersetze Hampelmänner durch Seitschritte, Sprungkniebeugen durch kontrollierte Kniebeugen, Laufen auf der Stelle durch Marschieren und Burpees mit hoher Belastung durch Varianten mit Rückwärtsschritt. Schattenboxen, zügiges Gehen, Radfahren auf der Stelle und kontrollierte Step-ups können Atmung und Herzfrequenz ohne wiederholte harte Landungen steigern.`},{title:`Den Aufbau verbessern`,text:`Trainiere auf freiem, rutschfestem Boden. Eine Übungsmatte kann etwas Schall dämpfen und den Boden schützen, kann aber nicht verhindern, dass sich Vibrationen durch die Struktur fortsetzen. Senke Gewichte bewusst ab und stapele keine lose Ausrüstung. Prüfe, ob eine Step-Plattform oder Bank bei jeder Wiederholung wackelt und poltert.`},{title:`Intensität ohne Belastung`,text:`Wie hart sich Cardio anfühlt, hängt von deiner Anstrengung ab, und Springen ist nur ein Weg, sie zu steigern. Längere Intervalle, kürzere Pausen, die dich sich trotzdem erholen lassen, oder durchgehende Bewegung mit geringer Belastung bauen alle Kondition auf. Im Krafttraining können langsame kontrollierte Hebungen und Pausen harte Arbeit sein und leise bleiben, du musst dich also nicht beeilen, eine Einheit härter wirken zu lassen.`},{title:`TrainUp nutzen`,text:`Im Profil sind „Springen in Ordnung“ und „wie viel Lärm in Ordnung ist“ zwei getrennte Einstellungen. Wenn du beide begrenzt, lässt der Plan Sprünge, Seilspringen und andere stampfende Übungen weg und trainiert mit leiseren trotzdem auf dein Ziel hin. Eine Matte allein macht eine Sprungübung nicht leise.`}];var i=[{label:`CDC: Empfehlungen zur körperlichen Aktivität für Erwachsene`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`},{label:`CDC: Intensität der Aktivität messen und Sprechtest`,url:`https://www.cdc.gov/physicalactivity/basics/measuring/index.html`},{label:`ACE-Übungsbibliothek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`}];var r={sections:t,sources:i};export{r as default,t as sections,i as sources};